function UIWorldBossMainDialog:RefreshWorldBossInfo()
    local requestEnd = false
    worldBossComponent:RefreshWorldBossInfo(function()
        self.btnFightReadyServer:UpdateInfo()
        self.worldBossDetailsService:UpdateInfo()
        self.rankRewardService:UpdateInfo()
        self.damageRewardService:UpdateInfo()
        self.worldBossPlayerRankService:UpdateInfo()
        requestEnd = true
    end)
    -- 直到网络请求回复之前，都不要显示界面
    while not requestEnd do
        cs_coroutine.yield_return(Yielders.EndOfFrame)
    end
end

