    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CriWareUtils.PlayMusicById("bgm_world_boss")
        CfUtils.RefreshTopGoods({})
        self:RefreshWorldBossInfo()
        SetButtonAction(self.BtnTest, Bind(self, function()
            GameUtils.Toast(localize("世界BOSS结束"))
            Events.Broadcast(Constants.EventNames.WorldBossEnd)
