function UIWorldBossMainDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()

        self.btnFightReadyServer:Dispose()
        self.worldBossDetailsService:Dispose()
        self.rankRewardService:Dispose()

        if self.EventWorldBossBegin then
            Events.RemoveListener(Constants.EventNames.WorldBossBegin, self.EventWorldBossBegin)
            self.EventWorldBossBegin = nil
        end

        if self.EventWorldBossEnd then
            Events.RemoveListener(Constants.EventNames.WorldBossEnd, self.EventWorldBossEnd)
            self.EventWorldBossEnd = nil
        end

        if self._coRefresh then
            cs_coroutine.stop(self._coRefresh)
            self._coRefresh = nil
        end

        self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

